insert into public.daily_verses (id, book_id, chapter, verse_start, verse_end, explanation, theme) values
(0, 19, 23, 1, 3, 'David pictures God as a shepherd who provides, leads and restores. The WEB uses "Yahweh", the personal name of God in Hebrew, where many translations print "the LORD". Today, notice one place where you need rest and bring it to him.', 'Rest'),
(1, 50, 4, 6, 7, 'Paul wrote these words from prison. He does not deny that worries are real; he invites us to turn each one into prayer with thanksgiving, and promises a peace that guards the heart even when circumstances have not changed.', 'Peace'),
(2, 23, 40, 31, 31, 'Isaiah spoke to people who felt worn out and forgotten in exile. Waiting on God here is active trust, not passive resignation, and the promise is renewed strength for the next step rather than an absence of effort.', 'Strength'),
(3, 40, 11, 28, 30, 'Jesus speaks to people weighed down by religious rules and daily burdens. A yoke was a tool for shared work: he does not promise no load at all, but a gentler way of carrying it alongside him.', 'Rest'),
(4, 25, 3, 22, 23, 'These lines sit in the middle of a book of grief written after Jerusalem fell. Hope here is not a denial of sorrow; it is a decision to remember God''s faithfulness while sorrow is still present.', 'Hope'),
(5, 6, 1, 9, 9, 'God spoke these words to Joshua as he took on a daunting new responsibility. The courage commanded is grounded not in Joshua''s own ability but in God''s presence going with him.', 'Courage'),
(6, 20, 3, 5, 6, 'Proverbs is practical wisdom for ordinary life. Trusting God "with all your heart" does not mean switching off your mind; it means holding your own understanding humbly and inviting God into every decision.', 'Guidance'),
(7, 43, 14, 27, 27, 'Jesus said this to his friends on the night before his death, knowing how frightened they would soon be. The peace he offers is different from the world''s because it does not depend on everything going well.', 'Peace'),
(8, 45, 8, 38, 39, 'Paul lists every power he can think of — death, life, the present, the future — and concludes that none of them can separate us from God''s love in Christ. It is one of the most confident statements of assurance in the New Testament.', 'Love'),
(9, 19, 46, 1, 3, 'This psalm imagines the whole earth shaking and still declares God a present help. Martin Luther''s hymn ‘A Mighty Fortress’ was inspired by it. A refuge is somewhere you run to, not somewhere you must earn your way into.', 'Refuge'),
(10, 33, 6, 8, 8, 'Micah summarises what God asks of his people in three phrases: act justly, love kindness, and walk humbly with God. It is a short verse that many Christians use as a daily check on how they are living.', 'Faithful living'),
(11, 47, 12, 9, 9, 'Paul had asked God three times to remove a painful difficulty. The answer he received was not removal but grace that was enough. Christians have long found comfort here when struggles do not go away.', 'Grace'),
(12, 19, 139, 13, 14, 'The psalmist marvels that God knew him even before birth. Whatever others say about you, this psalm invites you to see yourself as known, intended and valued by your Creator.', 'Identity'),
(13, 58, 11, 1, 1, 'Hebrews defines faith as confidence in what is hoped for and not yet seen. The chapter that follows tells the stories of ordinary, imperfect people who trusted God before they could see how things would turn out.', 'Faith'),
(14, 48, 5, 22, 23, 'Paul calls these qualities the "fruit" of the Spirit — they grow over time rather than being produced by willpower alone. Notice which one you would most like to see grow in you this season.', 'Character'),
(15, 62, 4, 18, 18, 'John contrasts fear of punishment with the security of being loved. Many Christians find this verse helpful when faith has felt driven by anxiety rather than trust.', 'Love over fear'),
(16, 49, 2, 8, 9, 'Paul insists that salvation is a gift received through faith, not a reward earned by effort. Christian traditions explain the relationship between faith and good works in different ways, but all affirm that grace comes first.', 'Grace'),
(17, 19, 34, 18, 18, 'This verse speaks directly to those who are hurting. It does not promise that pain will vanish, but that God draws near to the broken-hearted rather than keeping his distance.', 'Comfort'),
(18, 40, 6, 33, 34, 'In the Sermon on the Mount, Jesus invites his listeners to put God''s kingdom first and to face one day at a time. It is a gentle realism: each day has enough of its own concerns.', 'Trust'),
(19, 51, 3, 12, 13, 'Paul describes compassion, kindness, humility, gentleness and patience as clothing to put on each day. Forgiveness is modelled on the forgiveness Christians believe they have received.', 'Relationships'),
(20, 23, 41, 10, 10, 'God speaks to his people through Isaiah during a time of uncertainty. The promise is threefold: I will strengthen you, I will help you, I will uphold you.', 'Courage'),
(21, 45, 12, 12, 12, 'A short, practical verse: rejoice in hope, be patient in trouble, keep praying. Paul expected his readers to face real difficulty and offered three habits for getting through it.', 'Perseverance'),
(22, 19, 121, 1, 2, 'This is one of the ‘Songs of Ascents’ that pilgrims sang as they travelled up to Jerusalem. Looking at the hills, the traveller remembers that help comes not from the hills themselves but from their Maker.', 'Help'),
(23, 43, 8, 12, 12, 'Jesus spoke these words in the Temple, possibly during the Feast of Tabernacles when great lamps were lit. He presents himself as the light that guides people through darkness.', 'Light'),
(24, 59, 1, 5, 5, 'James encourages anyone facing a hard decision to ask God for wisdom, describing God as one who gives generously and without finding fault. It is an invitation to pray honestly about what you do not know.', 'Wisdom'),
(25, 60, 5, 7, 7, 'Peter wrote to Christians facing hardship and invited them to hand their anxieties to God. The reason given is simple: he cares for you.', 'Worry'),
(26, 36, 3, 17, 17, 'This lesser-known prophet offers a tender picture of God rejoicing over his people with singing. It is a reminder that God''s attitude toward his people includes joy, not merely tolerance.', 'Delight'),
(27, 19, 103, 2, 5, 'David speaks to his own soul and tells it not to forget God''s benefits. Naming specific good gifts is an ancient practice that can steady the heart on difficult days.', 'Gratitude'),
(28, 40, 5, 3, 6, 'The Beatitudes open the Sermon on the Mount and turn ordinary expectations upside down: the poor in spirit, the mourning and the meek are called blessed. Jesus speaks hope to people who feel they have little.', 'Blessing'),
(29, 21, 3, 1, 4, 'The Teacher observes that life moves through seasons — weeping and laughing, mourning and dancing. It can be a comfort to recognise that the season you are in is real, and that it is not the only one.', 'Seasons'),
(30, 66, 21, 4, 4, 'In John''s vision of a renewed creation, God wipes away every tear. Christians have read this as a promise that sorrow and death do not have the final word.', 'Hope')
insert into public.devotional_content (slug, title, book_id, chapter, verse_start, verse_end, reflection, takeaway, reflection_question, prayer, focus_tags, is_premium, sort_order) values ('the-shepherd-who-restores', 'The Shepherd Who Restores', 19, 23, 1, 4, 'Psalm 23 may be the most familiar passage in the whole Bible. It is read at weddings and funerals, stitched onto cushions and recited in hospital wards. Familiarity can make it easy to skim, so today, try reading it slowly, as if for the first time.
insert into public.devotional_content (slug, title, book_id, chapter, verse_start, verse_end, reflection, takeaway, reflection_question, prayer, focus_tags, is_premium, sort_order) values ('anxious-for-nothing', 'Turning Worry Into Prayer', 50, 4, 4, 7, '"In nothing be anxious." For anyone who has lain awake at three in the morning with a racing mind, these words can feel almost impossible. Paul surely cannot mean that anxiety simply switches off because we are told to stop it.
insert into public.devotional_content (slug, title, book_id, chapter, verse_start, verse_end, reflection, takeaway, reflection_question, prayer, focus_tags, is_premium, sort_order) values ('new-every-morning', 'Mercies That Are New Every Morning', 25, 3, 19, 24, 'The book of Lamentations is not a book most of us turn to for encouragement. It is a series of poems of grief written after the destruction of Jerusalem in 587 BC. The city lay in ruins, the Temple was burned, and many people had been killed or taken into exile. The writer does not hold back: he speaks of bitterness, of feeling walled in, of prayers that seem to go unheard.
insert into public.devotional_content (slug, title, book_id, chapter, verse_start, verse_end, reflection, takeaway, reflection_question, prayer, focus_tags, is_premium, sort_order) values ('come-to-me', 'An Invitation to the Weary', 40, 11, 28, 30, 'Of all the invitations Jesus gave, this may be one of the most tender: "Come to me, all you who labor and are heavily burdened, and I will give you rest."
insert into public.devotional_content (slug, title, book_id, chapter, verse_start, verse_end, reflection, takeaway, reflection_question, prayer, focus_tags, is_premium, sort_order) values ('love-that-holds', 'Nothing Can Separate Us', 45, 8, 31, 39, 'Romans 8 is often described as one of the high points of the New Testament, and today''s passage is its triumphant conclusion. Paul has spent seven chapters explaining the good news of God''s grace, and here he steps back and asks, "What then shall we say about these things?"
insert into public.devotional_content (slug, title, book_id, chapter, verse_start, verse_end, reflection, takeaway, reflection_question, prayer, focus_tags, is_premium, sort_order) values ('clothed-with-kindness', 'Clothed With Kindness', 51, 3, 12, 15, 'Every morning, most of us choose what to wear. In today''s passage Paul uses that ordinary habit as a picture of the Christian life: "Put on, therefore, as God''s chosen ones, holy and beloved, a heart of compassion, kindness, lowliness, humility, and perseverance."
insert into public.devotional_content (slug, title, book_id, chapter, verse_start, verse_end, reflection, takeaway, reflection_question, prayer, focus_tags, is_premium, sort_order) values ('grace-is-enough', 'When Grace Is Enough', 47, 12, 7, 10, 'Paul was one of the most influential leaders in the early church. He planted churches across the Roman world, wrote much of the New Testament and endured shipwrecks and imprisonments. Yet in today''s passage he talks openly about weakness.
insert into public.faith_journeys (slug, title, subtitle, description, day_count, focus_tags, is_premium, sort_order) values ('strengthen-your-faith-7', '7 Days to Strengthen Your Faith', 'A gentle week of foundations', 'A short journey through some of the Bible''s clearest pictures of what faith is, where it comes from and how it grows. Suitable whether you are exploring Christianity or looking to be refreshed.', 7, array['strengthening_faith','understanding_scripture','building_habits']::text[], false, 0) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, day_count = excluded.day_count, focus_tags = excluded.focus_tags, is_premium = excluded.is_premium, sort_order = excluded.sort_order;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 1, 'What faith is', 58, 11, 1, 3, 'The writer of Hebrews describes faith as assurance about things hoped for and conviction about things not yet seen. Faith is not pretending; it is trusting the character of God before every question has an answer. The rest of Hebrews 11 lists imperfect people who trusted God in exactly this way.', 'What is one thing you hope for that you cannot yet see?', 'Read the rest of Hebrews 11 and notice which person''s story you relate to most.', 'God, I want to trust you more than I do. Thank you that faith begins small. Help me to rely on who you are, even where I cannot see the whole picture. Amen.', 'Describe your faith right now in one honest sentence. What has shaped it?' from public.faith_journeys where slug = 'strengthen-your-faith-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 2, 'Faith as small as a seed', 40, 17, 19, 20, 'When the disciples asked why they had failed, Jesus spoke of faith as tiny as a mustard seed. The point is not the size of our faith but the greatness of the One it is placed in. Small, genuine trust in a great God is enough to begin with.', 'Where do you feel your faith is "too small"? How does this passage reframe that?', 'Look closely at a small seed, a bud or a leaf today, and let it remind you that growth often starts unseen.', 'Jesus, my faith sometimes feels tiny. Thank you that you can work with mustard-seed faith. Help it to grow, not by my effort alone, but by your grace. Amen.', 'Write about a time when a small step of trust led to something bigger than you expected.' from public.faith_journeys where slug = 'strengthen-your-faith-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 3, 'Honest faith with doubts', 41, 9, 21, 24, 'A desperate father asks Jesus for help and then admits, "I believe. Help my unbelief!" Jesus does not turn him away. This passage shows that faith and doubt can exist together, and that honesty about our doubts can itself be a prayer.', 'What doubts are you carrying that you have not yet said out loud to God?', 'Pray the father''s prayer — "I believe. Help my unbelief" — three times slowly today, perhaps at morning, midday and evening.', 'Lord, I believe; help my unbelief. I bring you my questions as well as my trust. Thank you that you welcome honest hearts. Amen.', 'List any questions or doubts you have about faith. Next to each, write one way you might explore it further.' from public.faith_journeys where slug = 'strengthen-your-faith-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 4, 'Faith that comes by hearing', 45, 10, 13, 17, 'Paul writes that faith comes from hearing the message about Christ. Faith grows as we spend time with God''s Word — reading it, hearing it read, and talking about it with others. It is nourished, much as a body is fed.', 'How regularly does Scripture shape your thinking at the moment?', 'Listen to a chapter of the Gospel of Mark today using the Listen button in the Bible reader.', 'Speak to me through your Word, Lord. Give me an appetite for Scripture and help me to understand what I read. Amen.', 'Which verse or story has stayed with you most from your reading so far? Why do you think it stuck?' from public.faith_journeys where slug = 'strengthen-your-faith-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 5, 'Faith tested', 59, 1, 2, 6, 'James encourages readers to view trials as opportunities for perseverance to grow. He is not saying that pain is good in itself, but that God can use difficult seasons to deepen trust. He also invites anyone lacking wisdom to ask God, who gives generously.', 'What difficulty are you facing where you need wisdom right now?', 'Write down one challenge you are facing and ask God specifically for wisdom about your next step.', 'Generous God, I ask for wisdom in the situation in front of me. Help me to persevere, and use even this season to deepen my trust in you. Amen.', 'Reflect on a past difficulty. How did it shape you? Where, looking back, can you see God''s care?' from public.faith_journeys where slug = 'strengthen-your-faith-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 6, 'Faith that acts', 59, 2, 14, 17, 'James insists that real faith shows itself in action, especially in caring for those in need. Christian traditions explain the relationship between faith and works in different ways, but all agree that living faith changes how we treat others.', 'Who around you might need practical care this week?', 'Do one quiet, practical act of kindness today for someone who will not be able to repay you.', 'Lord, let my faith be more than words. Open my eyes to the needs around me, and give me courage to act with love. Amen.', 'Describe the act of kindness you chose. How did it feel, and what did you notice?' from public.faith_journeys where slug = 'strengthen-your-faith-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 7, 'Faith rooted in love', 49, 3, 16, 19, 'Paul prays that his readers would be "rooted and grounded in love" and would grasp how wide, long, high and deep Christ''s love is. Faith is strongest when it is rooted not in our performance but in being deeply loved.', 'Which part of this prayer do you most need to be true for you?', 'Pray Paul''s prayer in verses 16–19 for yourself, then for someone you care about by name.', 'Father, strengthen me in my inner being. Root me in your love, and help me to grasp how wide and long and high and deep it is. Amen.', 'Looking back over these seven days, what has changed in how you understand faith?' from public.faith_journeys where slug = 'strengthen-your-faith-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.faith_journeys (slug, title, subtitle, description, day_count, focus_tags, is_premium, sort_order) values ('gratitude-7', '7 Days of Gratitude', 'Noticing God''s goodness, day by day', 'A week of short readings and simple practices to help you notice and give thanks for good gifts — including on days when gratitude does not come easily.', 7, array['finding_peace','building_habits','prayer']::text[], false, 1) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, day_count = excluded.day_count, focus_tags = excluded.focus_tags, is_premium = excluded.is_premium, sort_order = excluded.sort_order;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 1, 'Do not forget', 19, 103, 1, 5, 'David speaks to his own soul and tells it not to forget God''s benefits. Gratitude often begins as an act of remembering on purpose, especially when the mind naturally drifts toward what is wrong.', 'What good gift from God have you recently forgotten to notice?', 'Write a list of five specific good things from the past week, however small.', 'Lord, I do not want to forget your goodness. Thank you for the gifts I so easily overlook. Teach my soul to bless you. Amen.', 'Write your five good things and say a sentence about why each matters to you.' from public.faith_journeys where slug = 'gratitude-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 2, 'In every circumstance', 52, 5, 16, 18, 'Paul encourages believers to give thanks "in everything" — not necessarily for everything. Gratitude in hard times does not deny pain, but looks for God''s presence within it.', 'What is difficult right now, and what can you still give thanks for in the middle of it?', 'Set three moments in the day (for example, at each meal) to pause and say one sentence of thanks.', 'God, even in this difficult season I want to look for your hand. Thank you that you are with me. Teach me to pray and give thanks continually. Amen.', 'Write about something hard and, alongside it, one thing that has helped you through it.' from public.faith_journeys where slug = 'gratitude-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 3, 'The one who returned', 42, 17, 11, 19, 'Ten people were healed, but only one came back to thank Jesus — and he was a Samaritan, an outsider. Gratitude turns a gift into a relationship with the Giver.', 'Is there someone — God or a person — you have meant to thank but never have?', 'Send a short message of thanks to someone who has helped you, telling them specifically what they did.', 'Jesus, like the one who returned, I want to come back and thank you. Make me someone who notices and gives thanks. Amen.', 'Write a letter of thanks to God about one particular way he has cared for you.' from public.faith_journeys where slug = 'gratitude-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 4, 'Creation''s gifts', 19, 104, 10, 15, 'This psalm delights in water, grass, bread and wine as gifts from God''s hand. Everyday provisions are part of his care. Gratitude can be very ordinary and very physical.', 'Which everyday gift do you most take for granted?', 'Take a short walk outside, or sit by a window, and notice five things in creation you can thank God for.', 'Creator God, thank you for water, food, light and the beauty of the world. Open my eyes to your goodness in ordinary things. Amen.', 'Describe one moment today when you noticed beauty in creation.' from public.faith_journeys where slug = 'gratitude-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 5, 'Contentment', 50, 4, 11, 13, 'Paul says he has "learned" contentment in plenty and in need. Contentment is not natural; it is learned over time and draws on Christ''s strength rather than circumstances.', 'Where does comparison or "never enough" show up in your life?', 'Choose one area where you feel discontent and write three things you already have in that area.', 'Lord, teach me contentment. When I compare and grasp, remind me of what you have already given, and strengthen me in every circumstance. Amen.', 'What would it look like to be content in your current season, even if some things are still hoped for?' from public.faith_journeys where slug = 'gratitude-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 6, 'Thankful for people', 50, 1, 3, 6, 'Paul thanks God every time he remembers his friends in Philippi. Giving thanks for people can change how we see them and deepen our love for them.', 'Who are you thankful for, and have you told God about them?', 'Pray for three people by name today, thanking God for one specific quality in each.', 'Father, thank you for the people you have placed in my life. Bless them today, and carry on the good work you are doing in them. Amen.', 'Write about one person who has shaped your faith or your life for good.' from public.faith_journeys where slug = 'gratitude-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 7, 'The greatest gift', 47, 9, 12, 15, 'Paul ends a passage about generosity by exclaiming, "Thanks be to God for his unspeakable gift!" Christians understand this as the gift of Jesus himself. All other gratitude flows toward this centre.', 'How has this week of gratitude changed what you notice?', 'Give something away today — time, money or help — as a response of thanks.', 'Thanks be to you, God, for your indescribable gift. Let my whole life become a response of gratitude. Amen.', 'Look back over the week. Which practice would you like to keep as a daily habit?' from public.faith_journeys where slug = 'gratitude-7' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.faith_journeys (slug, title, subtitle, description, day_count, focus_tags, is_premium, sort_order) values ('finding-peace-14', '14 Days of Finding Peace', 'Scripture for anxious and unsettled seasons', 'Two weeks of passages and practices for times when your mind is busy and your heart is unsettled. This journey is not a substitute for professional support; if anxiety is overwhelming, please also speak to your GP or a counsellor.', 14, array['finding_peace','anxiety','prayer']::text[], true, 2) on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, day_count = excluded.day_count, focus_tags = excluded.focus_tags, is_premium = excluded.is_premium, sort_order = excluded.sort_order;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 1, 'Peace is a gift', 43, 14, 25, 27, 'Jesus spoke of leaving his peace with his friends on the night before his death. His peace is given, not manufactured, and it is different from the world''s peace because it does not depend on circumstances.', 'Where do you usually look for peace?', 'Sit quietly for three minutes and simply receive Jesus'' words: "My peace I give to you."', 'Jesus, I receive your peace. I cannot produce it myself. Settle my heart today. Amen.', 'Describe what peace would look and feel like for you right now.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 2, 'Bring every worry', 50, 4, 6, 7, 'Paul invites believers to bring every request to God with thanksgiving, and promises that God''s peace will guard their hearts and minds. Prayer gives worry somewhere to go.', 'What specific worries are on your mind today?', 'Write each worry on its own line, then turn each into a one-sentence prayer.', 'Lord, I bring you each of these worries. Thank you for listening. Guard my heart and mind with your peace. Amen.', 'List your worries and the prayers you wrote for them.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 3, 'He cares for you', 60, 5, 6, 7, 'Peter encourages readers to throw their anxieties onto God because he cares for them. The picture is of handing over a heavy load rather than continuing to carry it.', 'Do you really believe God cares about what worries you?', 'Each time a worry returns today, imagine placing it into God''s hands and say, ‘You care for me.’', 'Father, I cast my anxieties on you. Thank you that you care for me, not just in general but personally. Amen.', 'What worry was hardest to hand over today? Why?' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 4, 'Be still', 19, 46, 1, 11, 'The psalmist describes the earth shaking and the seas roaring, and yet God is a refuge and strength. Later in the psalm comes the invitation, "Be still, and know that I am God."', 'What feels unstable in your world right now?', 'Read Psalm 46 slowly, then spend two minutes in silence focusing on the words "Be still."', 'God, you are my refuge and strength. When everything shakes, help me to be still and know that you are God. Amen.', 'Write about what "refuge" means to you.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 5, 'Lilies and birds', 40, 6, 25, 27, 'Jesus points to the birds and the flowers as reminders of God''s care. He asks, "Which of you by being anxious can add one moment to his lifespan?" Worry rarely changes outcomes, but trust changes how we live.', 'What are you worrying about that is beyond your control?', 'Go outside, notice a bird or flower, and let it remind you of God''s attention to small things.', 'Father, you feed the birds and clothe the flowers. Help me to trust that you see and care for me too. Amen.', 'Separate your concerns into two lists: things I can act on, and things I can only entrust to God.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 6, 'One day at a time', 40, 6, 31, 34, 'Jesus encourages us to seek God''s kingdom first and not to worry about tomorrow, because each day has enough trouble of its own. Peace is often found in attending to today.', 'How much of your anxiety is about tomorrow rather than today?', 'Plan only today. When thoughts about tomorrow come, write them down and set them aside until tomorrow.', 'Lord, help me to live this day well and to leave tomorrow in your hands. Amen.', 'What is one thing you can do today to seek God''s kingdom first?' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 7, 'Perfect peace', 23, 26, 3, 4, 'Isaiah speaks of God keeping in perfect peace the one whose mind is steadfast because they trust in him. Peace and focus are connected; what we fix our thoughts on shapes our hearts.', 'What are your thoughts most often fixed on at the moment?', 'Choose a short verse from this week and repeat it slowly whenever your mind starts to race.', 'Faithful God, keep my mind steadfast on you. You are my everlasting rock. Amen.', 'Write down the verse you chose and why it matters to you.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 8, 'Lying down in peace', 19, 4, 6, 8, 'David ends this psalm with the words "In peace I will both lay myself down and sleep." Many people find their worries loudest at night; this psalm makes a bedtime prayer of trust.', 'How do you usually feel as you go to sleep?', 'Tonight, read verse 8 aloud before sleeping, and hand the day back to God.', 'Lord, I lay down this day and everything in it. You alone make me dwell in safety. Give me peaceful rest. Amen.', 'Write a short evening prayer you could use each night.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 9, 'Fear not', 23, 43, 1, 3, 'God tells his people, "Don''t be afraid, for I have redeemed you. I have called you by your name." The promise is not that there will be no waters or fire, but that God will be with them through both.', 'What "waters" or "fire" are you passing through?', 'Write your own name into verse 1 and read it aloud as a personal word of reassurance.', 'Lord, you have called me by name. When I pass through hard places, be with me. Amen.', 'What does it mean to you to be known and called by name?' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 10, 'The God who sees', 19, 139, 1, 6, 'David marvels that God knows when he sits and rises, and understands his thoughts from afar. Being fully known can be frightening — but here it becomes comforting, because the One who knows us also loves us.', 'Is being fully known by God comforting or uncomfortable to you? Why?', 'Tell God honestly about something you usually keep hidden, knowing he already sees and still loves you.', 'Lord, you know me completely. Thank you that you surround me with your presence. Help me to rest in being known. Amen.', 'Write a prayer of honesty about one area of your life.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 11, 'Peace with others', 45, 12, 16, 18, 'Paul urges believers to live peaceably with everyone "as much as it is up to you." Some conflict is beyond our control, but we can take responsibility for our part.', 'Is there a relationship where your peace is disturbed?', 'Consider one step you could take toward peace in a relationship, if it is safe and wise to do so.', 'God of peace, show me my part in the conflicts around me. Give me humility and wisdom. Amen.', 'Reflect on what "as much as it is up to you" means in a relationship you are thinking about.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 12, 'Come away and rest', 41, 6, 30, 32, 'After a busy season, Jesus invited his disciples to come away to a quiet place and rest. Rest is not selfish or lazy; Jesus himself made space for it.', 'When did you last rest without guilt?', 'Schedule a short block of genuine rest this week and protect it.', 'Jesus, thank you for inviting me to come away and rest. Help me to receive rest without guilt. Amen.', 'What drains you, and what restores you? Write two short lists.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 13, 'The God of all comfort', 47, 1, 3, 5, 'Paul calls God "the Father of mercies and God of all comfort," who comforts us so that we can comfort others. Our own experience of comfort can become a gift to someone else.', 'How has God comforted you, and who might need that comfort now?', 'Reach out to someone going through a hard time with a short, kind message.', 'God of all comfort, thank you for comforting me. Help me to share that comfort with others. Amen.', 'Write about a time you received comfort that you could now pass on.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.journey_days (journey_id, day_number, theme, book_id, chapter, verse_start, verse_end, explanation, reflection_question, activity, prayer, journal_prompt) select id, 14, 'Peace that remains', 4, 6, 24, 26, 'This ancient blessing was given for priests to speak over God''s people. It ends with the words "and give you peace." The Hebrew word shalom means wholeness and well-being, not merely an absence of trouble.', 'What has shifted in you over these fourteen days?', 'Speak this blessing over yourself, and then over someone you love.', 'Lord, bless me and keep me. Make your face shine on me. Turn your face toward me and give me peace. Amen.', 'Write which practice from this journey you want to carry forward.' from public.faith_journeys where slug = 'finding-peace-14' on conflict (journey_id, day_number) do update set theme = excluded.theme, book_id = excluded.book_id, chapter = excluded.chapter, verse_start = excluded.verse_start, verse_end = excluded.verse_end, explanation = excluded.explanation, reflection_question = excluded.reflection_question, activity = excluded.activity, prayer = excluded.prayer, journal_prompt = excluded.journal_prompt;
insert into public.quiz_questions (category, difficulty, question, options, correct_index, explanation, reference) values
('trivia', 'beginner', 'Who built an ark to survive the flood?', array['Abraham','Noah','Moses','Elijah']::text[], 1, 'God told Noah to build an ark of gopher wood for his family and the animals.', 'Genesis 6:13-14'),
('trivia', 'beginner', 'In which town was Jesus born?', array['Nazareth','Jerusalem','Bethlehem','Capernaum']::text[], 2, 'Jesus was born in Bethlehem of Judea, though he grew up in Nazareth.', 'Matthew 2:1'),
('trivia', 'beginner', 'How many disciples did Jesus choose to be the Twelve?', array['7','10','12','70']::text[], 2, 'Jesus appointed twelve to be with him and to be sent out to preach.', 'Mark 3:14'),
('trivia', 'beginner', 'What did David use to defeat Goliath?', array['A sword','A sling and a stone','A spear','A bow and arrow']::text[], 1, 'David struck Goliath with a stone from his sling.', '1 Samuel 17:49'),
('trivia', 'beginner', 'Which book comes first in the New Testament?', array['Mark','John','Acts','Matthew']::text[], 3, 'Matthew opens the New Testament with a genealogy of Jesus.', 'Matthew 1:1'),
('trivia', 'beginner', 'What did Jesus feed five thousand people with?', array['Seven loaves and a few fish','Five loaves and two fish','Twelve loaves','Manna from heaven']::text[], 1, 'The disciples found five loaves and two fish, which Jesus blessed and shared.', 'Matthew 14:17-21'),
('trivia', 'beginner', 'Who was swallowed by a great fish?', array['Jonah','Peter','Jeremiah','Daniel']::text[], 0, 'God prepared a great fish to swallow Jonah, and he was inside it three days and three nights.', 'Jonah 1:17'),
('trivia', 'beginner', 'According to Genesis 1, what did God create on the first day?', array['Animals','Light','Plants','The sun and moon']::text[], 1, 'God said, "Let there be light," and there was light.', 'Genesis 1:3-5'),
('trivia', 'intermediate', 'Which apostle denied knowing Jesus three times?', array['John','Thomas','Peter','Judas']::text[], 2, 'Peter denied Jesus three times before the rooster crowed, as Jesus had said.', 'Luke 22:60-62'),
('trivia', 'intermediate', 'On the road to which city was Saul (Paul) converted?', array['Damascus','Antioch','Rome','Corinth']::text[], 0, 'A light from heaven flashed around Saul as he approached Damascus.', 'Acts 9:3-4'),
('trivia', 'intermediate', 'Which psalm begins with the words that Yahweh is "my shepherd"?', array['Psalm 1','Psalm 23','Psalm 51','Psalm 119']::text[], 1, 'Psalm 23 opens, "Yahweh is my shepherd: I shall lack nothing."', 'Psalms 23:1'),
('trivia', 'intermediate', 'In Paul''s letter, which three things "remain"?', array['Faith, hope and love','Joy, peace and patience','Grace, truth and mercy','Wisdom, strength and courage']::text[], 0, 'Paul concludes, "now faith, hope, and love remain—these three. The greatest of these is love."', '1 Corinthians 13:13'),
('trivia', 'intermediate', 'Which river was Jesus baptised in?', array['The Nile','The Euphrates','The Jordan','The Tigris']::text[], 2, 'Jesus came from Nazareth and was baptised by John in the Jordan.', 'Mark 1:9'),
('trivia', 'intermediate', 'In the parable, who stopped to help the man beaten by robbers?', array['A priest','A Levite','A Samaritan','A tax collector']::text[], 2, 'A priest and a Levite passed by, but a Samaritan had compassion on him.', 'Luke 10:33-34'),
('trivia', 'intermediate', 'How many days and nights did Jesus fast in the wilderness?', array['7','12','40','3']::text[], 2, 'Jesus fasted forty days and forty nights before being tempted.', 'Matthew 4:1-2'),
('trivia', 'advanced', 'Which prophet was taken up to heaven in a whirlwind?', array['Elisha','Elijah','Isaiah','Ezekiel']::text[], 1, 'Elijah went up by a whirlwind into heaven as Elisha watched.', '2 Kings 2:11'),
('trivia', 'advanced', 'Who was the first king of Israel?', array['David','Solomon','Saul','Samuel']::text[], 2, 'Samuel anointed Saul as the first king over Israel.', '1 Samuel 10:1'),
('trivia', 'advanced', 'Which book of the Bible does not mention God by name?', array['Ruth','Esther','Jonah','Lamentations']::text[], 1, 'The book of Esther famously contains no explicit mention of God, though many see his providence throughout. Mordecai''s words in Esther 4:14 hint at it.', 'Esther 4:14'),
('trivia', 'advanced', 'What was the name of the garden where Jesus prayed before his arrest (as named by Matthew and Mark)?', array['Eden','Gethsemane','Golgotha','Bethany']::text[], 1, 'Jesus went with his disciples to a place called Gethsemane to pray.', 'Matthew 26:36'),
('trivia', 'advanced', 'Who wrote down the vision recorded in Revelation, while on the island of Patmos?', array['Peter','Paul','John','James']::text[], 2, 'John describes being on the isle called Patmos when he received the revelation.', 'Revelation 1:9'),
('character', 'beginner', 'I led the Israelites out of Egypt and received the Ten Commandments on Mount Sinai. Who am I?', array['Joshua','Aaron','Moses','Abraham']::text[], 2, 'Moses brought the people out of Egypt and received the law at Sinai.', 'Exodus 20:1-3'),
('character', 'beginner', 'I was thrown into a den of lions but God shut their mouths. Who am I?', array['Daniel','Joseph','Jonah','Samson']::text[], 0, 'Daniel told the king, "My God has sent his angel, and has shut the lions'' mouths."', 'Daniel 6:22'),
('character', 'beginner', 'I was sold by my brothers and later became a ruler in Egypt. Who am I?', array['Benjamin','Joseph','Jacob','Isaac']::text[], 1, 'Joseph''s brothers sold him, yet he rose to govern Egypt and later forgave them.', 'Genesis 45:4-5'),
('character', 'intermediate', 'I said to my mother-in-law, "Where you go, I will go." Who am I?', array['Naomi','Esther','Ruth','Hannah']::text[], 2, 'Ruth refused to leave Naomi and committed herself to Naomi''s people and God.', 'Ruth 1:16'),
('character', 'intermediate', 'I was a tax collector who climbed a sycamore tree to see Jesus. Who am I?', array['Matthew','Zacchaeus','Nicodemus','Bartimaeus']::text[], 1, 'Zacchaeus was short, so he ran ahead and climbed a sycamore tree.', 'Luke 19:2-4'),
('character', 'intermediate', 'I came to Jesus at night and he told me I must be born anew. Who am I?', array['Nicodemus','Lazarus','Joseph of Arimathea','Thomas']::text[], 0, 'Nicodemus, a Pharisee and ruler, came to Jesus by night.', 'John 3:1-3'),
('character', 'intermediate', 'I said I would not believe unless I saw the nail marks in Jesus'' hands. Who am I?', array['Peter','Thomas','Philip','Andrew']::text[], 1, 'Thomas doubted, and Jesus later invited him to see and believe.', 'John 20:24-25'),
('character', 'advanced', 'I prayed for a son at the tabernacle and dedicated Samuel to the Lord. Who am I?', array['Sarah','Rachel','Hannah','Elizabeth']::text[], 2, 'Hannah prayed in deep distress and later brought Samuel to serve at Shiloh.', '1 Samuel 1:10-11'),
('character', 'advanced', 'I was a seller of purple cloth whose heart the Lord opened as Paul spoke in Philippi. Who am I?', array['Priscilla','Lydia','Dorcas','Phoebe']::text[], 1, 'Lydia, from the city of Thyatira, listened to Paul and was baptised with her household.', 'Acts 16:14-15'),
('character', 'advanced', 'I rebuilt the walls of Jerusalem after serving as cupbearer to the Persian king. Who am I?', array['Ezra','Nehemiah','Zerubbabel','Haggai']::text[], 1, 'Nehemiah was cupbearer to King Artaxerxes before returning to rebuild the walls.', 'Nehemiah 2:1-5');
